// Shared pieces for the shell views: scenario context (site / date / window) carried in the URL,
// the LOLA hillshade map with numbered markers, and small formatting helpers.
// Every number comes from data/ (LOLA + SPICE pipeline). Missing data is "N/D", never 0.
// Source of truth: this .tsx file (Preact). common.js is generated by `npm --prefix web run build:ts`.
// Kept imperative inside the JSX: the hillshade and hour-strip canvases (pixel loops drawn in a ref callback).
import { h, Fragment, type ComponentChildren, type VNode } from "../../vendor/preact/preact.module.js";
import { num } from "../../ds/components.js";
import { Badge } from "../../ds/ui.js";
import { buildHash, type RouteCtx } from "../../ds/router.js";
import { loadSites, siteSeries, regionGrid, timeFromQuery, isoHour, fmtDate, HOUR_MS, type Site, type SitesData, type Series, type Query } from "../data.js";

export const WINDOWS = [7, 14, 28, 56];          // window length options (days)
export const LETTERS = ["A", "B", "C"];

export interface Scenario { data: SitesData; site: Site; t0: number; days: number; hours: number; }

// Attribute-reflecting twins of selected/value: the old DOM builder used setAttribute, Preact's selected/value are properties.
const selAttr = (on: boolean) => (on ? { defaultSelected: true } : {});

/** Scenario from the URL: { data, site, t0, days, hours }. Unknown ?site falls back to the first real site. */
export async function scenario(ctx: RouteCtx): Promise<Scenario> {
  const data = await loadSites();
  const site = data.sites.find(s => s.id === ctx.site) || data.sites[0];
  const days = WINDOWS.includes(Number(ctx.query.d)) ? Number(ctx.query.d) : 28;
  let t0 = timeFromQuery(ctx.query, data.window);
  // keep the whole window inside the computed series
  t0 = Math.min(t0, data.window.end - days * 24 * HOUR_MS);
  return { data, site, t0, days, hours: days * 24 };
}

/** Sites picked for comparison (?a=&b=&c=). Explicit letters win; otherwise the originating
 *  ?site= is A and the remaining slots take the next distinct real sites (BR-01). */
export function pickedSites(data: SitesData, query: Query): Site[] {
  const known = (id: string | undefined): id is string => data.sites.some(s => s.id === id);
  const explicit = LETTERS.map(L => query[L.toLowerCase()]);
  const fill = [query.site, ...data.sites.map(s => s.id)].filter((id): id is string => known(id) && !explicit.includes(id));
  const ids = explicit.map(id => id || fill.shift());
  return ids.map(id => data.sites.find(s => s.id === id)).filter((s): s is Site => Boolean(s));
}

/** Navigate to the same route with an updated query (keeps the rest of it). */
export function setQuery(ctx: RouteCtx, patch: Record<string, string | null | undefined>): void {
  location.hash = buildHash(ctx.path, { ...ctx.query, ...patch });
}

/** Context bar: site · date · window. Changes go to the URL so links reproduce the view. */
export function ContextBar({ ctx, sc, siteSelect = true }: { ctx: RouteCtx; sc: Scenario; siteSelect?: boolean }): VNode {
  const min = isoHour(sc.data.window.start).slice(0, 10), max = isoHour(sc.data.window.end - sc.hours * HOUR_MS).slice(0, 10);
  return (
    <div class="ctx glass" role="group" aria-label="Cenário">
      {siteSelect ? <Fragment>
        <label class="row"><span class="lbl-s">Local</span>
          <select aria-label="Local" onChange={e => setQuery(ctx, { site: (e.target as HTMLSelectElement).value })}>
            {sc.data.sites.map(s => <option value={s.id} {...selAttr(s.id === sc.site.id)}>{s.name}</option>)}
          </select></label>
        <span class="dot" aria-hidden="true">·</span>
      </Fragment> : null}
      <label class="row"><span class="lbl-s">Início</span>
        <input type="date" aria-label="Início da janela (UTC)" defaultValue={isoHour(sc.t0).slice(0, 10)} min={min} max={max}
          onChange={e => { const v = (e.target as HTMLInputElement).value; if (v) setQuery(ctx, { t: v }); }} /></label>
      <span class="dot" aria-hidden="true">·</span>
      <select aria-label="Duração da janela" onChange={e => setQuery(ctx, { d: (e.target as HTMLSelectElement).value })}>
        {WINDOWS.map(d => <option value={String(d)} {...selAttr(d === sc.days)}>{d + " dias"}</option>)}
      </select>
    </div>
  );
}

/** Series for several sites; a failed load becomes { error } so the view shows N/D for it. */
export interface Loaded { site: Site; series?: Series; error?: string; }
export async function seriesFor(sites: Site[]): Promise<Loaded[]> {
  return Promise.all(sites.map(s => siteSeries(s).then((series): Loaded => ({ site: s, series }), (e: Error): Loaded => ({ site: s, error: e.message }))));
}

export const pct = (v: unknown) => num(v, 0, "%");
export const hrs = (v: unknown) => num(v, 0, " h");
export { fmtDate, isoHour, HOUR_MS };

/** "VAL/EST/SIM/N/D" helper for a metric value: N/D when not finite, else the given kind. */
export function sealFor(v: unknown, kind?: string): VNode | null { return Number.isFinite(v) ? (kind ? <Badge kind={kind} /> : null) : <Badge kind="nd" />; }

/** Shared proof rows for the LOLA + SPICE window metrics (definition, horizon, step, ephemeris, version). */
export function seriesProof(series: Series | undefined, sc: Scenario, extra: [string, ComponentChildren][] = []): [string, ComponentChildren][] {
  const p = series && series.meta && series.meta.provenance;
  return [
    ...extra,
    ["Janela", fmtDate(sc.t0) + " → " + sc.days + " dias (passo 1 h)"],
    ["Horizonte", p ? "Raios sobre LOLA LDEM_80S_80M, 1° de azimute, até " + num(p.ray_parameters.max_distance_m / 1000, 0, " km") : "N/D"],
    ["Efeméride", p ? p.ephemeris : "N/D"],
    ["Versão", p ? p.generator : "N/D"],
    ["Status", series && series.meta ? series.meta.science_status : "N/D"],
  ];
}

/** Text download (CSV/JSON) without a server; Blob URL revoked after use. */
export function download(name: string, text: string, type: string): void {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.setAttribute("href", url); a.setAttribute("download", name);
  document.body.append(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}


// Joel Moon HD relief (LOLA 80 m near the pole, same stereographic projection) laid exactly over the 2D
// hillshade canvas; the markers stay on their stereographic x/y. Hardware WebGL only; ?relief=2d, no
// WebGL or a lost context keep the 400 m hillshade underneath.
const RELIEF_2D = typeof location !== "undefined" && new URLSearchParams(location.search).get("relief") === "2d";
function hdRelief(canvas: HTMLCanvasElement, cx: number, cy: number, spanX: number): void {
  const box = canvas.parentElement;
  if (RELIEF_2D || !box || box.dataset.relief) return;
  box.dataset.relief = "lola-2d";
  import("../../moon-hd/stereo-relief.js").then(m => m.mountStereoRelief(box, canvas.nextSibling as Element | null, () => {
    box.dataset.relief = "lola-2d"; canvas.style.visibility = "";
  })).then(hd => {
    if (!hd) return;
    const place = () => {
      if (!canvas.isConnected) { ro.disconnect(); hd.dispose(); return; }
      const w = canvas.clientWidth, h = canvas.clientHeight;
      Object.assign(hd.canvas.style, { inset: "auto", left: canvas.offsetLeft + "px", top: canvas.offsetTop + "px", width: w + "px", height: h + "px" });
      hd.draw(cx, cy, w, h, spanX / Math.max(1, w));
    };
    const ro = new ResizeObserver(place); ro.observe(canvas);
    canvas.style.visibility = "hidden"; box.dataset.relief = "moonhd"; place();
  }).catch(() => {});
}

/**
 * LOLA region hillshade (illustrative shading, NOT an illumination simulation) with numbered site markers.
 * Marker positions come from the sites' stereographic x/y (data/sites.json). The canvas pixels are drawn
 * imperatively in a ref callback (per-pixel loop), everything else is JSX.
 */
export async function regionMap(sites: Site[], selectedId: string, onSelect?: (id: string) => void): Promise<VNode> {
  const grid = await regionGrid();
  // crop to the sites' bounding box plus a margin so the markers are readable
  // square frame around the sites (plus margin) so the map never gets taller than it is wide
  const xs = sites.map(s => s.stereo_x_m), ys = sites.map(s => s.stereo_y_m), pad = 25000;
  const half = Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys)) / 2 + pad;
  const cx = (Math.max(...xs) + Math.min(...xs)) / 2, cy = (Math.max(...ys) + Math.min(...ys)) / 2;
  const x0 = Math.max(grid.x0, cx - half), x1 = Math.min(grid.x0 + grid.nx * grid.dx, cx + half);
  const y0 = Math.max(grid.y0, cy - half), y1 = Math.min(grid.y0 + grid.ny * grid.dx, cy + half);
  const i0 = Math.floor((x0 - grid.x0) / grid.dx), i1 = Math.ceil((x1 - grid.x0) / grid.dx);
  const j0 = Math.floor((y0 - grid.y0) / grid.dx), j1 = Math.ceil((y1 - grid.y0) / grid.dx);
  const W = i1 - i0, H = j1 - j0;
  const paint = (canvas: HTMLCanvasElement | null) => {
    if (!canvas) return;
    const g = canvas.getContext("2d") as CanvasRenderingContext2D, img = g.createImageData(W, H);
    const lx = -0.6, ly = 0.6, lz = 0.53; // fixed light direction for hillshade (illustrative only)
    for (let r = 0; r < H; r++) {
      const j = j1 - 1 - r; // canvas row 0 = max y (north up in the stereographic frame)
      for (let c = 0; c < W; c++) {
        const i = i0 + c, k = (r * W + c) * 4;
        const z = grid.at(i, j), zx = grid.at(Math.min(i + 1, grid.nx - 1), j) - grid.at(Math.max(i - 1, 0), j), zy = grid.at(i, Math.min(j + 1, grid.ny - 1)) - grid.at(i, Math.max(j - 1, 0));
        let v = 0;
        if (Number.isFinite(z) && Number.isFinite(zx) && Number.isFinite(zy)) {
          const nx = -zx / (2 * grid.dx), ny = -zy / (2 * grid.dx), n = Math.hypot(nx, ny, 1);
          const shade = Math.max(0, (nx * lx + ny * ly + lz) / n);
          const elev = (z - grid.min) / (grid.max - grid.min);
          v = Math.round(20 + 150 * shade + 60 * elev);
        }
        img.data[k] = img.data[k + 1] = img.data[k + 2] = Math.min(255, v); img.data[k + 3] = 255;
      }
    }
    g.putImageData(img, 0, 0);
    hdRelief(canvas, (grid.x0 + i0 * grid.dx) + W * grid.dx / 2, (grid.y0 + j0 * grid.dx) + H * grid.dx / 2, W * grid.dx);
  };
  const km = ((W * grid.dx) / 1000).toFixed(0);
  return (
    <div class="mapcard solid">
      <div class="mapbox">
        <canvas width={String(W)} height={String(H)} role="img" ref={paint}
          aria-label={"Relevo LOLA do polo sul com " + sites.length + " locais numerados. Sombreamento ilustrativo, não é simulação de iluminação."} />
        <div class="mlabels">
          {sites.map((s, n) => {
            const left = ((s.stereo_x_m - (grid.x0 + i0 * grid.dx)) / (W * grid.dx)) * 100;
            const top = (1 - (s.stereo_y_m - (grid.y0 + j0 * grid.dx)) / (H * grid.dx)) * 100;
            const pos = { left: left + "%", top: top + "%" }; // CSSOM: allowed by the CSP
            return <Fragment>
              <span class={"mname" + (s.id === selectedId ? " sel" : "")} style={pos}>{s.name.replace(/\s*\(.*\)$/, "")}</span>
              <button type="button" class="mk" aria-label={(n + 1) + ". " + s.name} aria-pressed={s.id === selectedId} style={pos}
                onClick={() => onSelect && onSelect(s.id)}>{String(n + 1)}</button>
            </Fragment>;
          })}
        </div>
      </div>
      <div class="maplegend glass">
        <strong>Relevo LOLA · Moon HD do Joel (80 m; sem WebGL: 400 m)</strong>
        <div class="ramp" aria-hidden="true" />
        <div class="t3">{"Sombreado ilustrativo, não é iluminação. Quadro ≈ " + km + " km, norte da grade estereográfica para cima."}</div>
      </div>
    </div>
  );
}

/** One canvas strip per site: hourly Sun (or Earth) visibility over the window (pixels drawn in a ref callback). */
export function HourStrip({ series, t0, hours, body }: { series: Series; t0: number; hours: number; body: "sun" | "earth" }): VNode {
  const W = Math.min(hours, 1344);
  const paint = (c: HTMLCanvasElement | null) => {
    if (!c) return;
    const g = c.getContext("2d") as CanvasRenderingContext2D, m = body === "sun" ? series.sunMargin : series.earthMargin;
    const cs = getComputedStyle(document.documentElement);
    const on = cs.getPropertyValue(body === "sun" ? "--c-sun" : "--c-earth").trim(), off = cs.getPropertyValue("--c-track").trim(), nd = cs.getPropertyValue("--c-unk").trim();
    const i0 = Math.ceil((t0 - series.start) / HOUR_MS);
    let vis = 0, n = 0;
    for (let x = 0; x < W; x++) {
      const i = i0 + Math.floor((x * hours) / W);
      const ok = i >= 0 && i < series.count;
      g.fillStyle = ok ? (m[i] >= 0 ? on : off) : nd;
      if (ok) { n++; if (m[i] >= 0) vis++; }
      g.fillRect(x, 0, 1, 14);
    }
    c.setAttribute("aria-label", (body === "sun" ? "Sol" : "Terra") + " visível em " + (n ? Math.round((100 * vis) / n) : "N/D") + "% das horas da janela");
  };
  return <canvas width={String(W)} height="14" class="hstrip" role="img" ref={paint} />;
}
